#define main original_main
#include "../gru2-cuda/main.cu"
#undef main
struct Case{int S,B,I,H,L,M;bool zero;std::vector<std::vector<float>>a;std::vector<float>expected;std::vector<float*>d;float*out,*ha,*hb,*la,*lb;};
static std::vector<float>fixture_values(size_t n,int a){std::vector<float>out(n);for(size_t i=0;i<n;++i)out[i]=float(int((17*i+13*a)%31)-15)/float(a==2||a==3?128:64);return out;}
static std::vector<double> oracle(Case&c){std::vector<double>hidden(c.a[5].begin(),c.a[5].end()),output;for(int t=0;t<c.S;++t){std::vector<double>current(c.a[0].begin()+t*c.B*c.I,c.a[0].begin()+(t+1)*c.B*c.I);int size=c.I;for(int l=0;l<c.L;++l){std::vector<double>next(c.B*c.H);for(int b=0;b<c.B;++b)for(int h=0;h<c.H;++h){double ig[3],hg[3];for(int g=0;g<3;++g){ig[g]=c.a[3][(l*3+g)*c.H+h];hg[g]=c.a[4][(l*3+g)*c.H+h];for(int k=0;k<size;++k)ig[g]+=current[b*size+k]*c.a[1][((l*3+g)*c.H+h)*c.M+k];for(int k=0;k<c.H;++k)hg[g]+=hidden[(l*c.B+b)*c.H+k]*c.a[2][((l*3+g)*c.H+h)*c.H+k];}double r=1/(1+exp(-(ig[0]+hg[0]))),z=1/(1+exp(-(ig[1]+hg[1]))),n=tanh(ig[2]+r*hg[2]);next[b*c.H+h]=(1-z)*n+z*hidden[(l*c.B+b)*c.H+h];}std::copy(next.begin(),next.end(),hidden.begin()+l*c.B*c.H);current=next;size=c.H;}output.insert(output.end(),current.begin(),current.end());}output.insert(output.end(),hidden.begin(),hidden.end());return output;}
int main(){std::vector<Case>cases;std::vector<float>prefix;for(int id=0;id<2;++id){Case c; c.S=id?4:3;c.B=id?2:3;c.I=id?5:37;c.H=id?7:35;c.L=id?2:3;c.M=std::max(c.I,c.H);c.zero=id;std::vector<size_t>sizes{size_t(c.S*c.B*c.I),size_t(c.L*3*c.H*c.M),size_t(c.L*3*c.H*c.H),size_t(c.L*3*c.H),size_t(c.L*3*c.H),size_t(c.L*c.B*c.H)};for(int a=0;a<6;++a)c.a.push_back(fixture_values(sizes[a],a+1));if(id)for(int a=1;a<5;++a)std::fill(c.a[a].begin(),c.a[a].end(),0);else for(int l=1;l<c.L;++l)for(int g=0;g<3;++g)for(int h=0;h<c.H;++h)for(int k=c.H;k<c.M;++k)c.a[1][((l*3+g)*c.H+h)*c.M+k]=55.25f;for(auto&a:c.a){prefix.insert(prefix.end(),a.begin(),a.end());float*ptr;CUDA_CHECK(cudaMalloc(&ptr,a.size()*4));CUDA_CHECK(cudaMemcpy(ptr,a.data(),a.size()*4,cudaMemcpyHostToDevice));c.d.push_back(ptr);}for(int v:{c.S,c.B,c.I,c.H,c.L})prefix.push_back(v);CUDA_CHECK(cudaMalloc(&c.out,c.S*c.B*c.H*4));CUDA_CHECK(cudaMalloc(&c.ha,c.L*c.B*c.H*4));CUDA_CHECK(cudaMalloc(&c.hb,c.L*c.B*c.H*4));CUDA_CHECK(cudaMalloc(&c.la,c.B*c.H*4));CUDA_CHECK(cudaMalloc(&c.lb,c.B*c.H*4));cases.push_back(c);}auto run=[&](Case&c,int repeats,std::vector<float>&output){const float*last=nullptr;CUDA_CHECK(cudaDeviceSynchronize());auto t=std::chrono::steady_clock::now();for(int k=0;k<repeats;++k)last=gru(c.d[0],c.d[1],c.d[2],c.d[3],c.d[4],c.d[5],c.out,c.ha,c.hb,c.la,c.lb,c.S,c.B,c.I,c.H,c.L,c.M);CUDA_CHECK(cudaDeviceSynchronize());double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/repeats;output.resize(c.S*c.B*c.H+c.L*c.B*c.H);CUDA_CHECK(cudaMemcpy(output.data(),c.out,c.S*c.B*c.H*4,cudaMemcpyDeviceToHost));CUDA_CHECK(cudaMemcpy(output.data()+c.S*c.B*c.H,last,c.L*c.B*c.H*4,cudaMemcpyDeviceToHost));return elapsed;};for(auto&c:cases){std::vector<float>unused;run(c,1,unused);}for(int tr=1;tr<=5;++tr){std::vector<float>out=prefix;double elapsed=0,err=0;for(auto&c:cases){std::vector<float>got;elapsed+=run(c,3,got);auto expected=oracle(c);for(size_t i=0;i<got.size();++i)err=std::max(err,std::abs(double(got[i])-expected[i]));out.insert(out.end(),got.begin(),got.end());}bool ok=err<=1e-4;for(float x:out)ok&=std::isfinite(x);std::string path="trial_"+std::to_string(tr)+".bin";FILE*f=fopen(path.c_str(),"wb");fwrite(out.data(),4,out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":25422,\"max_abs_error\":%.17g,\"timing_region\":\"sum_two_multilayer_gru_forward_means\",\"jit_excluded\":true,\"internal_repeats\":3,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":25422,\"byte_order\":\"little\"}}\n",tr,elapsed,ok?"true":"false",err,path.c_str());if(!ok)return 3;}for(auto&c:cases){for(auto ptr:c.d)cudaFree(ptr);cudaFree(c.out);cudaFree(c.ha);cudaFree(c.hb);cudaFree(c.la);cudaFree(c.lb);}return 0;}
